// OpenAPI schema 子集：请求/响应双向校验（纯函数，正反用例）
function validate(schema, value, path) {
  path = path || '$';
  const errors = [];
  const t = schema.type;
  if (t === 'object') {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) return [path + ': expected object'];
    for (const req of schema.required || []) if (!(req in value)) errors.push(path + '.' + req + ': required');
    const props = schema.properties || {};
    for (const [k, v] of Object.entries(value)) {
      if (!props[k]) {
        if (schema.additionalProperties === false) errors.push(path + '.' + k + ': additional property not allowed');
        continue;
      }
      errors.push(...validate(props[k], v, path + '.' + k));
    }
    return errors;
  }
  if (t === 'string') {
    if (typeof value !== 'string') return [path + ': expected string'];
    if (schema.minLength != null && value.length < schema.minLength) errors.push(path + ': minLength is ' + schema.minLength);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errors.push(path + ': must match ' + schema.pattern);
    return errors;
  }
  if (t === 'integer') {
    if (!Number.isInteger(value)) return [path + ': expected integer'];
    if (schema.minimum != null && value < schema.minimum) errors.push(path + ': minimum is ' + schema.minimum);
    if (schema.maximum != null && value > schema.maximum) errors.push(path + ': maximum is ' + schema.maximum);
    return errors;
  }
  if (t === 'boolean') { if (typeof value !== 'boolean') return [path + ': expected boolean']; return errors; }
  return errors;
}

